//! Every counter in `counters.toml`, as constants: one [`CounterId`] per entry and the
//! [`COUNTERS`] table. Generated by `scripts/gen-counters.py`; do not edit. Change
//! `counters.toml` and run `just gen-counters`; `just lint-counters` fails while this
//! file is stale (ADR 0012).

use super::{CounterDef, CounterId, Kind, Scope};

/// `counters.allocated`, a static gauge: Metadata records in the allocated state, this counter's own record included.
pub const COUNTERS_ALLOCATED: CounterId = CounterId(0);

/// `counters.allocation_failed`, a static counter: Counter allocations refused because every record was in use: the counters file is full, and whatever needed the counter was refused with it.
pub const COUNTERS_ALLOCATION_FAILED: CounterId = CounterId(1);

/// `publication.position`, a instance gauge: The producer position of one publication's log buffer, written by the driver on its duty cycle from a load it makes at most once every two milliseconds, so at most two milliseconds behind the publisher (ADR 0022, ADR 0032); key: correlation id (i64), session id (i32), stream id (i32), little-endian; label text: the three in decimal, space-separated.
pub const PUBLICATION_POSITION: CounterId = CounterId(2);

/// `publication.limit`, a instance gauge: The position up to which one publication may write: the slowest subscriber's position plus the publication window, written by the driver; key and label as publication.position.
pub const PUBLICATION_LIMIT: CounterId = CounterId(3);

/// `subscription.position`, a instance gauge: How far one subscription has read one publication's stream, written by the subscriber after each poll with a release store; key: correlation id (i64), session id (i32), stream id (i32), little-endian; label text: the three in decimal, space-separated.
pub const SUBSCRIPTION_POSITION: CounterId = CounterId(4);

/// `publication.unblocked`, a static counter: Stale claims the driver turned into padding frames because a publisher claimed and did not commit within the unblock timeout (spec/log-buffer.md, The driver).
pub const PUBLICATION_UNBLOCKED: CounterId = CounterId(5);

/// `log_buffer.rejected_position`, a static counter: Subscriber positions the driver found outside the spec's bounds and refused to use; the client that wrote one is evicted (ADR 0010).
pub const LOG_BUFFER_REJECTED_POSITION: CounterId = CounterId(6);

/// `log_buffer.rejected_tail`, a static counter: Tail counters the driver found inconsistent with the active term count and refused to use; the publication is closed (ADR 0010).
pub const LOG_BUFFER_REJECTED_TAIL: CounterId = CounterId(7);

/// `log_buffer.rejected_frame`, a static counter: Frames a subscriber found outside spec/frame.md's bounds in a term and reported; nothing after such a frame is delivered on that image.
pub const LOG_BUFFER_REJECTED_FRAME: CounterId = CounterId(8);

/// `command_ring.unblocked`, a static counter: Padding records the driver wrote over a claim in the command ring that a client made and did not commit within the unblock timeout (spec/command-ring.md, Unblocking).
pub const COMMAND_RING_UNBLOCKED: CounterId = CounterId(9);

/// `command_ring.rejected_tail`, a static counter: Tail positions the driver found outside the command ring's bounds when it unblocked and refused to use (ADR 0010): the ring is corrupt and the driver reads nothing more from it (spec/command-ring.md, Unblocking).
pub const COMMAND_RING_REJECTED_TAIL: CounterId = CounterId(10);

/// `command_ring.rejected_record`, a static counter: Records the driver found outside the command ring's bounds, a length or type no client writes by the protocol (ADR 0010): the driver reads nothing more from the ring (spec/command-ring.md, Reading).
pub const COMMAND_RING_REJECTED_RECORD: CounterId = CounterId(11);

/// `client.timed_out`, a static counter: Clients the driver timed out because no command of theirs arrived within the client liveness timeout; their publications and subscriptions were removed and a client timeout event sent (spec/client-protocol.md, Liveness and timeouts).
pub const CLIENT_TIMED_OUT: CounterId = CounterId(12);

/// `client_protocol.rejected_command`, a static counter: Commands the driver refused at decoding, for their channel or for a field outside its bound: a message too short to carry a correlation id, an unknown type, a message of the wrong length, a bad string, a channel that is not cavalry:ipc, or a replay length below -1 (spec/client-protocol.md, What the driver rejects); the client got an error event when its correlation id was readable.
pub const CLIENT_PROTOCOL_REJECTED_COMMAND: CounterId = CounterId(13);

/// `client_protocol.errors`, a static counter: Error events the driver sent, whatever the code: every command this version refused after the ring delivered it (spec/client-protocol.md, Error codes); the causes with a counter of their own are client_protocol.rejected_command, driver.registry_full and driver.log_create_failed.
pub const CLIENT_PROTOCOL_ERRORS: CounterId = CounterId(14);

/// `driver.registry_full`, a static counter: Commands refused with error code 10 because the driver's registry of clients, publications, subscriptions, images, recordings or replays, its bound on replay publications (live or lingering after their replay ended), the recorder's or the replayer's request queue, or the counters file, was at capacity; the error message names which (spec/client-protocol.md, Sizes; ADR 0036).
pub const DRIVER_REGISTRY_FULL: CounterId = CounterId(15);

/// `driver.log_create_failed`, a static counter: Log buffers the driver could not create or size, refused with error code 12: the filesystem under the driver directory is full or not writable (spec/client-protocol.md, Commands).
pub const DRIVER_LOG_CREATE_FAILED: CounterId = CounterId(16);

/// `conductor.idle_strategy`, a static gauge: The idle strategy the conductor runs, what its thread does on a duty cycle that found no work, stored once when the driver starts: 0 backoff, 1 yield, 2 busy-spin.
pub const CONDUCTOR_IDLE_STRATEGY: CounterId = CounterId(17);

/// `counters.allocations`, a static counter: Counter allocations made since the driver started, the static counters' own records included: every record that went from unused or reclaimed to allocated, the transition counters.allocated adds one for, so that counters.allocations minus counters.freed is counters.allocated (spec/counters-file.md, Metadata record).
pub const COUNTERS_ALLOCATIONS: CounterId = CounterId(18);

/// `counters.freed`, a static counter: Counters freed since the driver started: every record that went from allocated to reclaimed, the transition counters.allocated loses one for; a reclaimed record is allocated again after the counter reuse timeout.
pub const COUNTERS_FREED: CounterId = CounterId(19);

/// `recording.started`, a static counter: Recordings the driver started: a catalog slot taken, the time index and the first segment file created, the two position counters allocated and recording ready sent (spec/client-protocol.md, Commands).
pub const RECORDING_STARTED: CounterId = CounterId(20);

/// `recording.stopped`, a static counter: Recordings the driver stopped, by stop recording, at a publication's end of stream, or after a failed write or a frame that failed its check; each sent recording stopped with the stop position (spec/client-protocol.md, Commands).
pub const RECORDING_STOPPED: CounterId = CounterId(21);

/// `recording.write_failed`, a static counter: Recordings the recorder stopped because a write or a sync of theirs to the segment file or the time index failed, or because the writes or syncs of their stop did, each counted once. After a write that failed with no sync failing the recording stopped at the position written; after a sync that failed, or a stop that did, at the position last synced, its catalog slot left live for the next start's recovery (spec/client-protocol.md, Commands; ADR 0064; ADR 0065).
pub const RECORDING_WRITE_FAILED: CounterId = CounterId(22);

/// `recording.start_failed`, a static counter: Start recording commands refused with error code 12 because the recording's time index or first segment file could not be created in the log directory (spec/client-protocol.md, Commands). The recording's catalog slot may already be taken: a start that fails at its files leaves its slot valid, stopped at the start position, so the catalog's slots used are at most recording.started plus these plus the driver.registry_full refusals of a start.
pub const RECORDING_START_FAILED: CounterId = CounterId(23);

/// `recording.catalog_full`, a static counter: Start recording commands refused with error code 10 because the catalog holds every one of its 1048576 slots (spec/durable-log.md, Catalog header).
pub const RECORDING_CATALOG_FULL: CounterId = CounterId(24);

/// `recording.recovered`, a static counter: Recordings found live, or with a torn stop, when the driver opened the log directory, whose stop fields recovery rebuilt from their files (spec/durable-log.md, The driver).
pub const RECORDING_RECOVERED: CounterId = CounterId(25);

/// `recording.invalidated`, a static counter: Catalog slots recovery set to state 2 because their files cannot repair them: an empty slot before the last, a creation checksum that fails, or a segment file missing between the start and the last (spec/durable-log.md, The driver).
pub const RECORDING_INVALIDATED: CounterId = CounterId(26);

/// `recording.index_rewritten`, a static counter: Time indexes recovery wrote again with their start entry, gave a first entry, or truncated to whole entries in order or to the entries at or before the rebuilt stop (spec/durable-log.md, The driver).
pub const RECORDING_INDEX_REWRITTEN: CounterId = CounterId(27);

/// `recording.catalog_truncated`, a static counter: Catalog files recovery truncated to whole slots because a crash left bytes past the last slot: 0 or 1 at each driver start (spec/durable-log.md, The driver).
pub const RECORDING_CATALOG_TRUNCATED: CounterId = CounterId(28);

/// `recording.slot_dropped`, a static counter: Empty last catalog slots recovery dropped because a crash tore a recording's creation: 0 or 1 at each driver start, and the next recording takes the id (spec/durable-log.md, The driver).
pub const RECORDING_SLOT_DROPPED: CounterId = CounterId(29);

/// `recording.files_removed`, a static counter: Files recovery removed: segment files wholly past a rebuilt stop, and the files of a deleted recording that were still present (spec/durable-log.md, The driver).
pub const RECORDING_FILES_REMOVED: CounterId = CounterId(30);

/// `recording.position`, a instance gauge: The position of one recording up to which the recorder has written its segment files, what the operating system holds, stored with a release store after each block; the publisher's limit respects it (spec/log-buffer.md, The driver); key: recording id (i64), little-endian; label text: the recording id, the session id and the stream id in decimal, space-separated.
pub const RECORDING_POSITION: CounterId = CounterId(31);

/// `recording.synced_position`, a instance gauge: The position of one recording up to which a sync has made its segment files and time index durable, stored with a release store after each sync, at most a second behind recording.position; key and label as recording.position.
pub const RECORDING_SYNCED_POSITION: CounterId = CounterId(32);

/// `replay.started`, a static counter: Replays the driver started: the replay's publication created at the start position, its counters allocated and replay ready sent (spec/client-protocol.md, Commands; ADR 0030).
pub const REPLAY_STARTED: CounterId = CounterId(33);

/// `replay.stopped`, a static counter: Replays that ended, for any reason: each sent replay stopped with the position reached and the reason; replay.ended, replay.not_connected and replay.failed count the reasons other than a stop replay command (spec/client-protocol.md, Commands).
pub const REPLAY_STOPPED: CounterId = CounterId(34);

/// `replay.ended`, a static counter: Replays that reached their end position or their recording's stop position, reason 0 of replay stopped: the subscriber saw everything it asked for.
pub const REPLAY_ENDED: CounterId = CounterId(35);

/// `replay.not_connected`, a static counter: Replays the driver ended, reason 2 of replay stopped, because their publication had no subscriber for the replay connect timeout, from the start or from the moment the last subscriber went; over cavalry:udp the replay has a subscriber while its publication is connected, from the first status message without the send-setup flag until the connection timeout passes without one (spec/udp.md, The sender), so a replay nobody answers ends after the replay connect timeout from its start, and one whose receiver went after the connection timeout and then the replay connect timeout (spec/client-protocol.md, Liveness and timeouts; ADR 0043).
pub const REPLAY_NOT_CONNECTED: CounterId = CounterId(36);

/// `replay.failed`, a static counter: Replays that ended on a failure, reason 3 of replay stopped: a segment file of the recording could not be read, or a frame in it failed a check, which log_buffer.rejected_frame counts as well; the position in the event is the last frame delivered.
pub const REPLAY_FAILED: CounterId = CounterId(37);

/// `replay.start_failed`, a static counter: Start replay commands refused after the driver took them, with error code 21 (a recording id the catalog does not hold as a valid recording), 24 (a recording a truncate recording, purge segments or purge recording is working on), 23 (a position out of range) or 12 (a segment file that could not be opened); a start the registries refuse with code 10 is driver.registry_full's, and a replay log that could not be created is driver.log_create_failed's (spec/client-protocol.md, Commands; ADR 0031).
pub const REPLAY_START_FAILED: CounterId = CounterId(38);

/// `replay.position`, a instance gauge: The position of one replay up to which the replayer has written the recording's frames into the replay's log, stored with a release store after each block; it moves no faster than the slowest subscriber's position plus the publication window over cavalry:ipc, or over cavalry:udp the replay publication's sender.position plus the publication window, paced by its sender.limit, which the receivers' status messages raise, and not at all with no subscriber or while the publication is not connected (spec/client-protocol.md, Commands; spec/udp.md, The sender; ADR 0043); key: replay session id (i64), little-endian; label text: the replay session id, the recording id, the replay publication's session id and its stream id in decimal, space-separated.
pub const REPLAY_POSITION: CounterId = CounterId(39);

/// `recording.truncated`, a static counter: Stopped recordings truncated to a position by `truncate recording`: the segment files past the position removed, the one holding it cut, the time index shortened and the stop written again (spec/client-protocol.md, Commands; ADR 0031).
pub const RECORDING_TRUNCATED: CounterId = CounterId(40);

/// `recording.segments_purged`, a static counter: Segment files removed by `purge segments`, one per file as the replayer removes it, once the recording's retained position was written past them, so the counter reads a purge's progress while it runs (spec/durable-log.md, The driver; ADR 0031; card 177).
pub const RECORDING_SEGMENTS_PURGED: CounterId = CounterId(41);

/// `recording.deleted`, a static counter: Stopped recordings deleted by `purge recording`: the slot's state written as 3, then the segment files and the time index removed; the slot stays, so the id never names another recording (ADR 0024, ADR 0031).
pub const RECORDING_DELETED: CounterId = CounterId(42);

/// `recording.retention_failed`, a static counter: Retention commands the files refused with error code 12: a segment file the replayer could not open or read for a truncate's frame check before the catalog write, or a file it could not remove, cut or extend after it, when the driver ran recovery's rule for the slot at once so that the slot and the files agree (spec/client-protocol.md, Commands; ADR 0031).
pub const RECORDING_RETENTION_FAILED: CounterId = CounterId(43);

/// `recording.bytes`, a instance gauge: The bytes one live recording's segment files take on disk, the segment file length times the files present, kept by the recorder at each roll and stored with a release store; key and label as recording.position; freed with it after the stop, after which `cavalry doctor` computes a stopped recording's bytes from its descriptor (ADR 0031).
pub const RECORDING_BYTES: CounterId = CounterId(44);

/// `sender.bytes_sent`, a static counter: Bytes of data and padding frames the sender put on the wire for every cavalry:udp publication, headers included (spec/udp.md, The sender).
pub const SENDER_BYTES_SENT: CounterId = CounterId(45);

/// `sender.frames_sent`, a static counter: Data and padding frames the sender put on the wire; a padding frame counts whether or not its header went out (spec/udp.md, The sender).
pub const SENDER_FRAMES_SENT: CounterId = CounterId(46);

/// `sender.setups_sent`, a static counter: Setup frames sent: one every setup interval until a publication's first status message without the send-setup flag, and one for each status message with it (spec/udp.md, The sender).
pub const SENDER_SETUPS_SENT: CounterId = CounterId(47);

/// `sender.heartbeats_sent`, a static counter: Heartbeats sent: one after each heartbeat interval without a data frame, once a publication has its first status message (spec/udp.md, Heartbeat).
pub const SENDER_HEARTBEATS_SENT: CounterId = CounterId(48);

/// `sender.retransmits_sent`, a static counter: NAKs answered with the frames of the range they name, from the publication's own term (spec/udp.md, The sender).
pub const SENDER_RETRANSMITS_SENT: CounterId = CounterId(49);

/// `sender.retransmitted_bytes`, a static counter: Bytes of frames sent again in answer to NAKs.
pub const SENDER_RETRANSMITTED_BYTES: CounterId = CounterId(50);

/// `sender.retransmit_overflow`, a static counter: NAKs dropped because a retransmit for another range was outstanding: one retransmit at a time, kept for the retransmit linger after it (spec/udp.md, The sender).
pub const SENDER_RETRANSMIT_OVERFLOW: CounterId = CounterId(51);

/// `sender.short_sends`, a static counter: Datagrams the socket took only part of; the sender position stays at the datagram's first frame and the burst is sent again on the next cycle.
pub const SENDER_SHORT_SENDS: CounterId = CounterId(52);

/// `sender.send_failed`, a static counter: Sends the operating system refused, EAGAIN, ENOBUFS, EINTR and ECONNREFUSED among them, on a send endpoint, counted and retried on the next cycle, and on a receive endpoint, where the receiver's status messages, NAKs and RTT answers are sent once each; no failure on a live socket errors the endpoint (spec/udp.md, The receiver).
pub const SENDER_SEND_FAILED: CounterId = CounterId(53);

/// `sender.flow_control_limited`, a static counter: Times a publication with a frame to send found its sender limit reached: the receiver's window is full, counted once on entry into that state (spec/udp.md, The sender).
pub const SENDER_FLOW_CONTROL_LIMITED: CounterId = CounterId(54);

/// `sender.naks_received`, a static counter: NAKs that arrived at a send endpoint for a publication it carries.
pub const SENDER_NAKS_RECEIVED: CounterId = CounterId(55);

/// `sender.naks_ignored`, a static counter: NAKs dropped: one whose position lies outside the resend window, from the sender position less half a term and the longest message up to the sender position, or one whose term offset is not below the publication's own term length or whose range runs past it, the term a replay's publication keeps from its recording (spec/udp.md, The sender; ADR 0043).
pub const SENDER_NAKS_IGNORED: CounterId = CounterId(56);

/// `sender.status_messages_received`, a static counter: Status messages that arrived at a send endpoint for a publication it carries, with or without the send-setup flag.
pub const SENDER_STATUS_MESSAGES_RECEIVED: CounterId = CounterId(57);

/// `sender.status_messages_rejected`, a static counter: Status messages ignored: one without the send-setup flag whose consumption position lies outside the window around the sender position, one whose consumption term offset the publication's own term does not hold, which a replay's publication keeps from its recording (ADR 0043), or one with the flag that asks a publication at its end of stream for a setup (spec/udp.md, The sender).
pub const SENDER_STATUS_MESSAGES_REJECTED: CounterId = CounterId(58);

/// `sender.rtt_replies_sent`, a static counter: RTT measurements with the reply flag answered: the same frame without the flag, the echo timestamp and the receiver id unchanged (spec/udp.md, The sender).
pub const SENDER_RTT_REPLIES_SENT: CounterId = CounterId(59);

/// `sender.position`, a instance gauge: The sender position of one cavalry:udp publication: the next byte the sender puts on the wire, stored by the sender with a release store after each burst; key as publication.position; label text: publication.position's three and the endpoint's registration id in decimal, space-separated, so that doctor names the endpoint.
pub const SENDER_POSITION: CounterId = CounterId(60);

/// `sender.limit`, a instance gauge: The sender limit of one cavalry:udp publication: the consumption position of the last accepted status message plus its receiver window length, never lowered; key and label as sender.position.
pub const SENDER_LIMIT: CounterId = CounterId(61);

/// `publication.connected`, a static counter: cavalry:udp publications whose first status message without the send-setup flag arrived: the publication's limit rises to the sender position plus the publication window from here (spec/udp.md, The sender).
pub const PUBLICATION_CONNECTED: CounterId = CounterId(62);

/// `publication.disconnected`, a static counter: cavalry:udp publications that passed the connection timeout without a status message: the limit falls to the sender position and the publisher reads not connected until the next one (spec/udp.md, The sender).
pub const PUBLICATION_DISCONNECTED: CounterId = CounterId(63);

/// `channel.opened`, a static counter: Endpoints whose socket was opened, bound and connected on the control plane as the command was handled: initializing to active (spec/udp.md, The receiver).
pub const CHANNEL_OPENED: CounterId = CounterId(64);

/// `channel.closed`, a static counter: Endpoints closed once their last publication's linger ended or their last subscription and image went: active to closing, the socket closed and the five counters freed after the reuse timeout (spec/udp.md, The receiver).
pub const CHANNEL_CLOSED: CounterId = CounterId(65);

/// `channel.status`, a instance gauge: One endpoint's state, the channel status indicator a client reads: 0 initializing, 1 active, 2 closing, -1 errored, which this version never stores; key: the endpoint's registration id (i64), the correlation id of the command that opened it, little-endian; label text: the resolved channel.
pub const CHANNEL_STATUS: CounterId = CounterId(66);

/// `channel.socket_rcvbuf`, a instance gauge: The receive buffer length one endpoint's socket holds, read back after the endpoint was opened; key and label as channel.status.
pub const CHANNEL_SOCKET_RCVBUF: CounterId = CounterId(67);

/// `channel.socket_sndbuf`, a instance gauge: The send buffer length one endpoint's socket holds, the operating system's, read back after the endpoint was opened; key and label as channel.status.
pub const CHANNEL_SOCKET_SNDBUF: CounterId = CounterId(68);

/// `channel.images`, a instance gauge: How many images one receive endpoint carries; 0 on a send endpoint; key and label as channel.status.
pub const CHANNEL_IMAGES: CounterId = CounterId(69);

/// `channel.publications`, a instance gauge: How many publications one send endpoint carries; 0 on a receive endpoint; the endpoint closes when it reaches 0 and the last linger ends; key and label as channel.status.
pub const CHANNEL_PUBLICATIONS: CounterId = CounterId(70);

/// `receiver.receive_failed`, a static counter: Receives the operating system refused on a send or a receive endpoint's socket, EAGAIN aside, counted and the poll retried; no failure on a live socket errors the endpoint (spec/udp.md, The receiver).
pub const RECEIVER_RECEIVE_FAILED: CounterId = CounterId(71);

/// `receiver.bytes_received`, a static counter: Bytes of data and padding frames the receiver accepted into an image, headers included (spec/udp.md, The receiver, step 2).
pub const RECEIVER_BYTES_RECEIVED: CounterId = CounterId(72);

/// `receiver.frames_received`, a static counter: Data and padding frames the receiver accepted into an image; a duplicate, which changes nothing, is not counted (spec/udp.md, The receiver, step 2).
pub const RECEIVER_FRAMES_RECEIVED: CounterId = CounterId(73);

/// `receiver.setups_received`, a static counter: Setup frames that arrived at a receive endpoint, wanted or not.
pub const RECEIVER_SETUPS_RECEIVED: CounterId = CounterId(74);

/// `receiver.setups_unwanted`, a static counter: Setup frames for a stream no subscription on the endpoint wants, dropped (spec/udp.md, The receiver, step 1).
pub const RECEIVER_SETUPS_UNWANTED: CounterId = CounterId(75);

/// `receiver.setups_elicited`, a static counter: Status messages with the send-setup flag sent for a session with no record, asking the sender for its setup frame: a data datagram or heartbeat arrived for a wanted stream from a sender whose setups stopped before this receiver had a subscription, once per pending setup timeout (spec/udp.md, The receiver, step 1).
pub const RECEIVER_SETUPS_ELICITED: CounterId = CounterId(76);

/// `receiver.heartbeats_received`, a static counter: Heartbeats accepted for an image: the high-water mark follows them, and with EOS they name the end of stream (spec/udp.md, Heartbeat).
pub const RECEIVER_HEARTBEATS_RECEIVED: CounterId = CounterId(77);

/// `receiver.status_messages_sent`, a static counter: Status messages sent for an image: one at its creation, then on the three triggers, the slowest reader a quarter window past the last, a window change, or the status message interval (spec/udp.md, The receiver, step 4).
pub const RECEIVER_STATUS_MESSAGES_SENT: CounterId = CounterId(78);

/// `receiver.naks_sent`, a static counter: NAKs sent for a gap: one after the NAK delay and one every NAK retry while the gap persists (spec/udp.md, The receiver, step 3).
pub const RECEIVER_NAKS_SENT: CounterId = CounterId(79);

/// `receiver.gaps_detected`, a static counter: Gaps first seen by the rebuild scan: a run of zero frame length words between the rebuild position and the next frame or the high-water mark, each a datagram lost or reordered on the wire (spec/udp.md, The receiver, step 3).
pub const RECEIVER_GAPS_DETECTED: CounterId = CounterId(80);

/// `receiver.under_runs`, a static counter: Data datagrams dropped because they began below the last status message's position: a late retransmit or a duplicate of what the subscribers have passed (spec/udp.md, The receiver, step 2).
pub const RECEIVER_UNDER_RUNS: CounterId = CounterId(81);

/// `receiver.over_runs`, a static counter: Data datagrams and heartbeats dropped because they ended more than half a term beyond the last status message's position: a sender past the window it was given (spec/udp.md, The receiver, step 2).
pub const RECEIVER_OVER_RUNS: CounterId = CounterId(82);

/// `receiver.rejected_datagrams`, a static counter: Data datagrams that failed the datagram check, dropped whole: a length not a multiple of 32, a frame that fails spec/frame.md's checks, a term offset that is not the running one, or frames past the end of the term (spec/udp.md, What a reader rejects).
pub const RECEIVER_REJECTED_DATAGRAMS: CounterId = CounterId(83);

/// `receiver.dropped_frames`, a static counter: Control frames and heartbeats a receive endpoint dropped because their version or type is not one this version reads, or they are too short (spec/udp.md, The datagram), and heartbeats whose term offset is not below their image's term length (spec/udp.md, What a reader rejects, term-offset).
pub const RECEIVER_DROPPED_FRAMES: CounterId = CounterId(84);

/// `receiver.dropped_pending`, a static counter: Setup frames, data datagrams and heartbeats dropped for a session pending a setup, the datagram that elicited the setup among them, with no status message sent for them (spec/udp.md, The receiver, step 1).
pub const RECEIVER_DROPPED_PENDING: CounterId = CounterId(85);

/// `receiver.dropped_in_progress`, a static counter: Setup frames, data datagrams and heartbeats dropped for a session in progress, between the setup handed to the conductor and its image, or because the queue to the conductor had no room for the setup (spec/udp.md, The receiver, step 1).
pub const RECEIVER_DROPPED_IN_PROGRESS: CounterId = CounterId(86);

/// `receiver.dropped_cool_down`, a static counter: Setup frames, data datagrams and heartbeats dropped for a session on cool-down, the 10 s after its image was retired, so that a late frame creates no second image (spec/udp.md, The receiver, step 5).
pub const RECEIVER_DROPPED_COOL_DOWN: CounterId = CounterId(87);

/// `receiver.dropped_unwanted`, a static counter: Data datagrams, heartbeats and RTT measurements dropped for a stream no subscription on the endpoint wants, a datagram with EOS for a session with no record, an RTT measurement for a session with no image, or one for another receiver (spec/udp.md, The receiver, steps 1 and 6).
pub const RECEIVER_DROPPED_UNWANTED: CounterId = CounterId(88);

/// `receiver.sessions_full`, a static counter: Datagrams for a session with no record dropped because the session table held 4096 records, with no status message sent (spec/udp.md, The receiver).
pub const RECEIVER_SESSIONS_FULL: CounterId = CounterId(89);

/// `receiver.rtt_replies_sent`, a static counter: RTT measurements with the reply flag answered for an image: the same frame without the flag, the echo timestamp and the receiver id unchanged (spec/udp.md, The receiver, step 6).
pub const RECEIVER_RTT_REPLIES_SENT: CounterId = CounterId(90);

/// `image.hwm_position`, a instance gauge: The high-water mark of one image: the highest position any accepted datagram or heartbeat reached, stored by the receiver with a release store; key: the image's registration id (i64), session id (i32), stream id (i32), little-endian, as subscription.position; label text: the three in decimal, space-separated.
pub const IMAGE_HWM_POSITION: CounterId = CounterId(91);

/// `image.rebuild_position`, a instance gauge: The rebuild position of one image: the end of the contiguous frames from its start, the furthest a subscriber can read, stored by the receiver with a release store; key and label as image.hwm_position.
pub const IMAGE_REBUILD_POSITION: CounterId = CounterId(92);

/// `image.created`, a static counter: Images created from a setup frame: the conductor made the log, allocated the counters and announced the image, and the receiver sent its first status message (spec/udp.md, The receiver, step 1).
pub const IMAGE_CREATED: CounterId = CounterId(93);

/// `image.ended`, a static counter: Images retired because their stream ended: a heartbeat with EOS named the end, the rebuild reached it, and every reader did too or the liveness timeout passed (spec/udp.md, The receiver, step 5).
pub const IMAGE_ENDED: CounterId = CounterId(94);

/// `image.timed_out`, a static counter: Images retired because no accepted datagram or heartbeat arrived for the image liveness timeout, 10 s (spec/udp.md, The receiver, step 5).
pub const IMAGE_TIMED_OUT: CounterId = CounterId(95);

/// `image.unsubscribed`, a static counter: Images retired because their last subscription on the endpoint and stream was removed, by remove subscription, client close or client timeout, with no unavailable image for a subscription its client removed (spec/udp.md, The receiver, step 5).
pub const IMAGE_UNSUBSCRIBED: CounterId = CounterId(96);

/// `image.removed`, a static counter: Retired images whose log the conductor unlinked after unavailable image went to the subscriptions that remained and their counters were freed (spec/udp.md, The receiver, step 5).
pub const IMAGE_REMOVED: CounterId = CounterId(97);

/// `subscription.add_deferred`, a static counter: `add subscription` commands on a `cavalry:udp` channel whose previous receive endpoint was still closing, held with nothing registered until the receiver closed it and then run as if they had just arrived (spec/client-protocol.md, Commands; ADR 0049).
pub const SUBSCRIPTION_ADD_DEFERRED: CounterId = CounterId(98);

/// `subscription.add_deferred_timed_out`, a static counter: `add subscription` commands that waited the closing endpoint wait, 5 s, for a `cavalry:udp` channel's previous receive endpoint to close and were answered with code 4, with nothing registered; the close that came later ran nothing for them (spec/client-protocol.md, Commands, Liveness and timeouts; ADR 0049).
pub const SUBSCRIPTION_ADD_DEFERRED_TIMED_OUT: CounterId = CounterId(99);

/// `subscription.add_deferred_waiting`, a static gauge: `add subscription` commands waiting now for a `cavalry:udp` channel's previous receive endpoint to close, each holding a slot of the subscriptions registry until the close runs it, its client goes or the closing endpoint wait refuses it (spec/client-protocol.md, Commands, Sizes; ADR 0049).
pub const SUBSCRIPTION_ADD_DEFERRED_WAITING: CounterId = CounterId(100);

/// `sender.flow_control_receivers_timed_out`, a static counter: Receivers dropped from a min publication's table for no status message within the flow control receiver timeout, 5 s; one dropped because its last status message carried end of stream, as every receiver's does after a clean close, is not counted; the sender limit then follows the slowest of the receivers that remain (spec/udp.md, The sender; ADR 0053, ADR 0054).
pub const SENDER_FLOW_CONTROL_RECEIVERS_TIMED_OUT: CounterId = CounterId(101);

/// `sender.flow_control_receivers_full`, a static counter: Status messages from a receiver a min publication's full table of 64 does not hold: accepted for the connection and not tracked, so the sender limit does not follow that receiver (spec/udp.md, The sender; ADR 0053).
pub const SENDER_FLOW_CONTROL_RECEIVERS_FULL: CounterId = CounterId(102);

/// `sender.flow_control_receivers`, a instance gauge: The receivers in one cavalry:udp publication's min table, each answering within the flow control receiver timeout, and once the publication is closed each whose stream ended too, kept until the linger ends, so that a clean close leaves it at the receivers that took the stream to its end; 0 under max, which keeps no table; key as sender.position; label text: sender.position's four, then the publication's strategy as fc=max or fc=min, space-separated, so that doctor reads which publications keep a table (ADR 0053, ADR 0056).
pub const SENDER_FLOW_CONTROL_RECEIVERS: CounterId = CounterId(103);

/// `channel.destinations`, a instance gauge: How many destinations one send endpoint of a control channel sends to, added with add destination and removed with remove destination; 0 on any other endpoint; key and label as channel.status (spec/udp.md, The sender; ADR 0053).
pub const CHANNEL_DESTINATIONS: CounterId = CounterId(104);

/// `recording.armed`, a static counter: Start recording commands on a cavalry:udp stream with a live subscription and no live publication or image, answered with operation success and held as an armed recording, at most one per receive endpoint and stream with a live subscription, so the subscriptions registry bounds them, until the stream's next image arrives or its last subscription on the endpoint goes; each ends in one of recording.armed_started, recording.armed_failed and recording.armed_dropped, so this counter less those three is the recordings armed or starting (spec/client-protocol.md, Commands, start recording; ADR 0059).
pub const RECORDING_ARMED: CounterId = CounterId(105);

/// `recording.armed_started`, a static counter: Armed recordings that started when the stream's next image arrived, at the image's join position, before the image was announced, recording ready sent to the arming client with the arming command's correlation id, the command's second answer after its operation success (spec/client-protocol.md, Commands, start recording; ADR 0059).
pub const RECORDING_ARMED_STARTED: CounterId = CounterId(106);

/// `recording.armed_dropped`, a static counter: Armed recordings dropped because the last subscription on their receive endpoint and stream went before an image arrived, by remove subscription, client close or client timeout, a receive endpoint that closes being one case of it, since the receiver creates no image for a stream no subscription wants; the arming command is answered a second time with error code 20 (spec/client-protocol.md, Commands, start recording; ADR 0059).
pub const RECORDING_ARMED_DROPPED: CounterId = CounterId(107);

/// `recording.armed_failed`, a static counter: Armed recordings whose start failed when the stream's next image arrived, at a step a start on a live image fails at: the recordings registry, the recorder's request queue, the catalog or the counters file at capacity (code 10), or the recording's files not created (code 12). Each also counts in that step's counter, driver.registry_full, recording.catalog_full or recording.start_failed; the arming command is answered a second time with error and the code, and the image is announced all the same and no longer held by the recording (spec/client-protocol.md, Commands, start recording; ADR 0059).
pub const RECORDING_ARMED_FAILED: CounterId = CounterId(108);

/// `cluster.commit_position`, a client gauge: The commit position one cluster member knows: the position the leader has found a quorum has appended, which never falls; an entry at or below it is committed and a service reads nothing above it (spec/cluster.md, The log). The member's consensus module adds the counter and stores the value with a release store; a service loads it with an acquire load before it polls the log; key: member id (i32), little-endian; label text: the member id in decimal.
pub const CLUSTER_COMMIT_POSITION: CounterId = CounterId(109);

/// `cluster.elections`, a client counter: Elections one cluster member began, from init: on starting, and each time it begins again after a failed or lost election (spec/cluster.md, Roles and the election). At most one more than cluster.elections_closed and cluster.elections_failed together, the one more being the election under way; key: member id (i32), little-endian; label text: the member id in decimal.
pub const CLUSTER_ELECTIONS: CounterId = CounterId(110);

/// `cluster.terms_led`, a client counter: Terms one cluster member began to lead, on entering leader log replication: cluster.role going to leader (spec/cluster.md, The appointed leader); key and label as cluster.elections.
pub const CLUSTER_TERMS_LED: CounterId = CounterId(111);

/// `cluster.leader_quorum_losses`, a client counter: Times the active members of one cluster leader fell below a quorum, a member being active while its last report is younger than the leader heartbeat timeout, 10 s; the appointed leader stays the leader and its commit position stops until a quorum reports again (spec/cluster.md, The appointed leader); key and label as cluster.elections.
pub const CLUSTER_LEADER_QUORUM_LOSSES: CounterId = CounterId(112);

/// `cluster.appointed_leader_behind`, a client counter: Members the appointed leader found holding a log ahead of its own, in canvass or in leader ready, once for each such member in an election; the leader does not lead, or does not close its election, while one reports so (spec/cluster.md, The appointed leader); key and label as cluster.elections.
pub const CLUSTER_APPOINTED_LEADER_BEHIND: CounterId = CounterId(113);

/// `cluster.log_images_lost`, a client counter: Times one cluster follower's image of its leader's log was no longer available, so that it began its election again at init (spec/cluster.md, Roles and the election); key and label as cluster.elections.
pub const CLUSTER_LOG_IMAGES_LOST: CounterId = CounterId(114);

/// `cluster.elections_failed`, a client counter: Elections one cluster member failed in a state and began again at init: a log it cannot join without a truncation, a replication or a catch-up, an image of the log that joined at another position, or a step that made no progress for the leader heartbeat timeout, 10 s (spec/cluster.md, Roles and the election); key and label as cluster.elections.
pub const CLUSTER_ELECTIONS_FAILED: CounterId = CounterId(115);

/// `cluster.leader_heartbeat_timeouts`, a client counter: Times one cluster follower heard nothing from its leader for the leader heartbeat timeout, 10 s, and began its election again at init (spec/cluster.md, Roles and the election); key and label as cluster.elections.
pub const CLUSTER_LEADER_HEARTBEAT_TIMEOUTS: CounterId = CounterId(116);

/// `cluster.leadership_terms_ignored`, a client counter: New leadership term messages one cluster member ignored for their term: below its candidate term in canvass, or not the term it follows once it has taken a leader (spec/cluster.md, Messages during an election); key and label as cluster.elections.
pub const CLUSTER_LEADERSHIP_TERMS_IGNORED: CounterId = CounterId(117);

/// `cluster.join_position_mismatches`, a client counter: Images of the log that joined one cluster follower at a position other than its append position, so that it failed its election and left the image (spec/cluster.md, Roles and the election, state 15); key and label as cluster.elections.
pub const CLUSTER_JOIN_POSITION_MISMATCHES: CounterId = CounterId(118);

/// `cluster.election_steps`, a client counter: Steps of one cluster member's election from one state to the next that neither begin it, fail it, close it nor make the member a leader: canvass to follower replay, follower replay to follower log init, follower log init to follower log await, follower log await to follower ready, leader log replication to leader replay, leader replay to leader init and leader init to leader ready (spec/cluster.md, Counters; ADR 0067). An election that closes makes three on its leader and four on a follower; key and label as cluster.elections.
pub const CLUSTER_ELECTION_STEPS: CounterId = CounterId(119);

/// `cluster.elections_closed`, a client counter: Elections one cluster member closed: leader ready to closed, its term's first entry appended, or follower ready to closed, its append position sent to its leader (spec/cluster.md, Counters; ADR 0067); key and label as cluster.elections.
pub const CLUSTER_ELECTIONS_CLOSED: CounterId = CounterId(120);

/// `cluster.role`, a client gauge: One cluster member's role: 0 follower, 1 candidate, 2 leader (spec/cluster.md, Counters). The member's consensus module adds the counter and stores it; key: member id (i32), little-endian; label text: the member id in decimal.
pub const CLUSTER_ROLE: CounterId = CounterId(121);

/// `cluster.election_state`, a client gauge: The state of one cluster member's election, the code spec/cluster.md, Roles and the election, gives it, 17 when no election runs; key: member id (i32), little-endian; label text: the member id in decimal.
pub const CLUSTER_ELECTION_STATE: CounterId = CounterId(122);

/// `cluster.leadership_term_id`, a client gauge: The term one cluster member leads or follows, -1 before the first; key: member id (i32), little-endian; label text: the member id in decimal.
pub const CLUSTER_LEADERSHIP_TERM_ID: CounterId = CounterId(123);

/// `cluster.append_position`, a client gauge: One cluster member's append position: the end of the contiguous span its recordings of the log hold, as a sync has made it durable (spec/cluster.md, The log; ADR 0060); key: member id (i32), little-endian; label text: the member id in decimal.
pub const CLUSTER_APPEND_POSITION: CounterId = CounterId(124);

/// `cluster.messages_rejected`, a client counter: Messages of the consensus stream one cluster member rejected, for any reason of spec/cluster.md, What a reader rejects; key: member id (i32), little-endian; label text: the member id in decimal.
pub const CLUSTER_MESSAGES_REJECTED: CounterId = CounterId(125);

